from pathlib import Path

cpp_path = Path(__file__).resolve().parents[1] / 'Source' / 'ModernPitchEngine.cpp'
cpp = cpp_path.read_text()

marker = 'PRIMITIVE_PERIOD_PATH_GEOMETRY_V2'
if marker not in cpp:
    anchor = '''    if (hypothesisCount <= 0)\n        return makeFreshRawDecision();\n\n    // TRANSITION_WAKES_DETECTOR_NOT_OUTPUT_V1\n'''
    if cpp.count(anchor) != 1:
        raise RuntimeError(
            f'primitive-period geometry anchor: expected one, found {cpp.count(anchor)}')

    insertion = '''    if (hypothesisCount <= 0)\n        return makeFreshRawDecision();\n\n    // PRIMITIVE_PERIOD_PATH_GEOMETRY_V2\n    // Different detector paths run at different cadences. A quarter/eighth-rate\n    // direct coordinate remains the path's newest physical measurement until\n    // that path is scheduled again; treating only age==0 as geometry erases the\n    // slow path between its own analysis hops. collectFreshCandidates() has\n    // already bounded each candidate by the path-specific age window.\n    //\n    // When two already-valid current hypotheses are octave siblings and the\n    // upper coordinate has its own recent, structurally strong direct witness,\n    // regard it as the shorter/primitive period. The lower coordinate remains\n    // valid family evidence. We alter ranking only by the minimum amount needed\n    // to order the exact composite score used to seed the decoder beam; no F0\n    // threshold is lowered and no coordinate is created without a direct path.\n    const auto hasRecentPrimitiveWitness = [&](float frequencyHz) noexcept\n    {\n        for (int candidateIndex = 0; candidateIndex < candidateCount; ++candidateIndex)\n        {\n            const auto& candidate = candidates[static_cast<std::size_t>(candidateIndex)];\n            if (!candidate.valid\n                || !std::isfinite(candidate.frequencyHz)\n                || centsDistance(candidate.frequencyHz, frequencyHz) > 55.0f)\n            {\n                continue;\n            }\n\n            const int maximumAge = candidate.pathIndex == 0 ? 2\n                : (candidate.pathIndex == 1 ? 3\n                   : (candidate.pathIndex == 2 ? 5 : 9));\n            if (candidate.ageInHops < 0 || candidate.ageInHops > maximumAge)\n                continue;\n\n            const float cleanliness = candidate.tonalCleanliness >= 0.0f\n                ? clamp01(candidate.tonalCleanliness) : 0.0f;\n            const float family = candidate.harmonicFamily >= 0.0f\n                ? clamp01(candidate.harmonicFamily) : 0.0f;\n\n            // Existing strong-family evidence only; this is not a new validity\n            // gate. The witness must already have survived analyse().\n            if (candidate.periodicity >= 0.60f\n                && family >= 0.68f\n                && cleanliness >= 0.68f)\n            {\n                return true;\n            }\n        }\n        return false;\n    };\n\n    constexpr float beamConsensusWeight = 0.26f;\n    constexpr float primitiveOrderingMargin = 0.035f;\n    for (int upperIndex = 0; upperIndex < hypothesisCount; ++upperIndex)\n    {\n        auto& upper = hypotheses[static_cast<std::size_t>(upperIndex)];\n        if (!upper.valid || upper.freshSupportMask == 0\n            || upper.directSupportCount < 1\n            || !hasRecentPrimitiveWitness(upper.frequencyHz))\n        {\n            continue;\n        }\n\n        for (int lowerIndex = 0; lowerIndex < hypothesisCount; ++lowerIndex)\n        {\n            if (lowerIndex == upperIndex)\n                continue;\n\n            auto& lower = hypotheses[static_cast<std::size_t>(lowerIndex)];\n            if (!lower.valid || lower.freshSupportMask == 0\n                || lower.directSupportCount < 1\n                || !(lower.frequencyHz < upper.frequencyHz)\n                || centsDistance(2.0f * lower.frequencyHz, upper.frequencyHz) > 42.0f)\n            {\n                continue;\n            }\n\n            const float lowerBeamRank = lower.evidenceScore\n                + beamConsensusWeight * lower.consensus;\n            const float upperBeamRank = upper.evidenceScore\n                + beamConsensusWeight * upper.consensus;\n            const float requiredLift = lowerBeamRank\n                + primitiveOrderingMargin - upperBeamRank;\n            if (requiredLift > 0.0f)\n                upper.evidenceScore += requiredLift;\n        }\n    }\n\n    std::sort(hypotheses.begin(),\n              hypotheses.begin() + hypothesisCount,\n              [](const ConsensusHypothesis& left,\n                 const ConsensusHypothesis& right)\n              {\n                  return left.evidenceScore + 0.26f * left.consensus\n                       > right.evidenceScore + 0.26f * right.consensus;\n              });\n\n    // TRANSITION_WAKES_DETECTOR_NOT_OUTPUT_V1\n'''
    cpp = cpp.replace(anchor, insertion, 1)
    cpp_path.write_text(cpp)

print('PRIMITIVE_PERIOD_PATH_GEOMETRY_V2 materialized')
